package mz.bam.seeky.android;
import android.content.*;import android.database.Cursor;import android.net.Uri;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.*;import java.util.*;import java.util.zip.*;import org.json.*;

/** Optional portable conversations and WAVs. Credentials are never sourced from these options. */
final class BackupExtras {
    static final Set<String> FOLDERS=new HashSet<>(Arrays.asList("study-materials","voice-notes","backgrounds","book-settings","book-covers","seeky-ai-conversations","narrations"));
    static final class Options{final boolean conversations,audio;Options(boolean conversations,boolean audio){this.conversations=conversations;this.audio=audio;}}
    static boolean mutable(String path){String parent=new File(path).getParentFile().getName();return parent.equals("book-settings")||parent.equals("seeky-ai-conversations");}
    static void collect(Context c,Map<String,File> files,Options options,boolean local)throws Exception{
        for(File f:BookSettings.activeFiles(c)){files.put(f.getPath(),f);JSONObject data=BookSettings.get(c,new JSONObject(new String(Files.readAllBytes(f.toPath()),StandardCharsets.UTF_8)).getString("hash"));String cover=data.optString("cover","");if(!cover.isEmpty()){File image=privateFile(c,new File(cover),"book-covers");files.put(cover,image);}}
        for(File settings:BookSettings.activeFiles(c)){JSONObject data=new JSONObject(new String(Files.readAllBytes(settings.toPath()),StandardCharsets.UTF_8));JSONObject profile=data.optJSONObject("profile");if(profile!=null&&!profile.optString("background_path").isEmpty()){String path=profile.getString("background_path");File audio=privateFile(c,new File(path),"backgrounds");files.put(path,audio);}}
        if(options.conversations||local){SeekyAiStore conversations=new SeekyAiStore(c);for(File f:conversations.activeFiles())files.put(f.getPath(),f);}
        try(PlusStore db=new PlusStore(c);Cursor rows=db.getReadableDatabase().query("audio_tracks",new String[]{"uri"},null,null,null,null,null)){while(rows.moveToNext()){Uri uri=Uri.parse(rows.getString(0));if("file".equals(uri.getScheme()))try{File f=privateFile(c,new File(uri.getPath()),"narrations");files.put(uri.getPath(),f);}catch(IOException ignored){}}}
    }
    static File privateFile(Context c,File file,String folder)throws IOException{File canonical=file.getCanonicalFile(),root=new File(c.getFilesDir(),folder).getCanonicalFile();if(!DiskWalker.inside(root,canonical)||!canonical.isFile())throw new IOException("Ficheiro privado indisponível.");return canonical;}
    static int external(Context c,ZipOutputStream zip,JSONArray entries,int number,java.util.function.BooleanSupplier cancelled,WorkspaceBackup.Progress progress)throws Exception{
        try(PlusStore db=new PlusStore(c);Cursor rows=db.getReadableDatabase().query("audio_tracks",new String[]{"uri","title"},null,null,null,null,"id")){while(rows.moveToNext()){
            WorkspaceBackup.check(cancelled);Uri uri=Uri.parse(rows.getString(0));if(!Arrays.asList("content","file").contains(uri.getScheme()))throw new IOException("Localização de narração inválida.");if(uri.getScheme().equals("file"))try{privateFile(c,new File(uri.getPath()),"narrations");continue;}catch(IOException ignored){}
            String name="payload/"+String.format(Locale.ROOT,"%06d",++number),old="/narrations/"+ReaderStore.digest(uri.toString())+".wav";progress.update("A incluir WAV · "+rows.getString(1));MessageDigest digest=MessageDigest.getInstance("SHA-256");long bytes=0;zip.putNextEntry(new ZipEntry(name));try(InputStream input=c.getContentResolver().openInputStream(uri)){if(input==null)throw new IOException("Uma narração não está acessível. Escolha a pasta novamente ou guarde sem WAVs externos.");byte[] header=new byte[12];int at=0;while(at<12){int n=input.read(header,at,12-at);if(n<0)throw new IOException("Narração WAV inválida.");at+=n;}if(!new String(header,0,4,StandardCharsets.US_ASCII).equals("RIFF")||!new String(header,8,4,StandardCharsets.US_ASCII).equals("WAVE"))throw new IOException("A narração já não corresponde ao WAV guardado.");zip.write(header);digest.update(header);bytes=12;byte[] buffer=new byte[65536];for(int n;(n=input.read(buffer))!=-1;){WorkspaceBackup.check(cancelled);bytes+=n;if(bytes>8589934592L)throw new IOException("WAV acima do limite da cópia.");zip.write(buffer,0,n);digest.update(buffer,0,n);}}zip.closeEntry();entries.put(new JSONObject().put("entry",name).put("kind","file").put("path",old).put("folder","narrations").put("bytes",bytes).put("sha256",WorkspaceBackup.hex(digest.digest())).put("original_uri",uri.toString()));
        }}return number;
    }
    static void typed(JSONObject preferences,String file,String key,String value)throws JSONException{JSONObject group=preferences.optJSONObject(file);if(group==null){group=new JSONObject();preferences.put(file,group);}group.put(key,new JSONObject().put("type","string").put("value",value));}
    static void restore(Context c,WorkspaceBackup.Staged staged,Map<String,String> paths,JSONObject preferences)throws Exception{
        JSONObject tools=preferences.optJSONObject("reading_tools"),workspace=tools==null?null:tools.optJSONObject("workspace_id");String token=workspace==null?"":workspace.optString("value","");JSONArray entries=staged.manifest.getJSONArray("entries");
        for(int i=0;i<entries.length();i++){JSONObject item=entries.getJSONObject(i);if(!item.optString("kind").equals("file"))continue;String old=item.getString("path"),folder=item.getString("folder");File target=new File(paths.get(old));if(item.has("original_uri")){String original=item.getString("original_uri");Uri uri=Uri.parse(original);if(original.length()>4096||!Arrays.asList("file","content").contains(uri.getScheme()))throw new IOException("Origem de narração inválida.");paths.put(original,Uri.fromFile(target).toString());}
            if(!folder.equals("book-settings")&&!folder.equals("seeky-ai-conversations"))continue;if(target.length()>2097152)throw new IOException("Preferência privada demasiado grande.");String raw=new String(Files.readAllBytes(target.toPath()),StandardCharsets.UTF_8);JsonBudget.check(raw,18,6000);JSONObject data=new JSONObject(raw);
            if(folder.equals("book-settings")){String hash=PlusStore.hash(data.getString("hash"));String cover=data.optString("cover","");if(paths.containsKey(cover))data.put("cover",paths.get(cover));JSONObject profile=data.optJSONObject("profile");if(profile!=null){String background=profile.optString("background_path","");if(paths.containsKey(background))profile.put("background_path",paths.get(background));}typed(preferences,"book_settings",hash,target.getPath());}
            else{SeekyAiStore.Session session=new SeekyAiStore.Session(data);if(!session.id().matches("[a-f0-9-]{36}"))throw new IOException("Conversa inválida.");String source=data.optString("uri","");for(Map.Entry<String,String> path:paths.entrySet())source=source.replace(path.getKey(),path.getValue());data.put("uri",source).put("workspace_id",token);typed(preferences,"reading_tools","conversation_file_"+session.id(),target.getPath());}
            File temp=new File(target.getParentFile(),target.getName()+".rewrite");try(FileOutputStream out=new FileOutputStream(temp)){out.write(data.toString().getBytes(StandardCharsets.UTF_8));out.getFD().sync();}Files.move(temp.toPath(),target.toPath(),StandardCopyOption.REPLACE_EXISTING);
        }
    }
    private BackupExtras(){}
}
